<?php require_once 'config.php';require_login();$u=current_user();$pageTitle='Feedback';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$rating=(int)($_POST['rating']??0);$message=trim($_POST['message']??'');if($rating<1||$rating>5||$message==='')$error='Choose a rating and enter your feedback.';else{$s=db()->prepare('INSERT INTO feedback(user_id,rating,message) VALUES(?,?,?)');$s->execute([$u['id'],$rating,$message]);flash('Thank you for helping us improve Capacity Connect.');redirect('feedback.php');}}$s=db()->prepare('SELECT * FROM feedback WHERE user_id=? ORDER BY created_at DESC');$s->execute([$u['id']]);$items=$s->fetchAll();require 'includes/header.php'; ?><section class="page-heading compact-heading"><span class="eyebrow">HELP US IMPROVE</span><h1>Your feedback <em>matters.</em></h1><p>Tell us what is working well and what would make your learning experience better.</p></section><section class="section narrow-section"><div class="panel"><h2>Share your experience</h2><?php if($error): ?><div class="alert error"><?= e($error) ?></div><?php endif; ?><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><label>Overall rating<select name="rating" required><option value="">Select a rating</option><option value="5">5 — Excellent</option><option value="4">4 — Very good</option><option value="3">3 — Good</option><option value="2">2 — Needs improvement</option><option value="1">1 — Poor</option></select></label><label>Your comments<textarea name="message" rows="5" required placeholder="What could we improve?"></textarea></label><button class="btn btn-primary">Send feedback →</button></form></div><?php if($items): ?><div class="panel previous-feedback"><h2>Your previous feedback</h2><?php foreach($items as $item): ?><article><b><?= (int)$item['rating'] ?>/5 rating</b><p><?= e($item['message']) ?></p><small><?= e(date('d M Y',strtotime($item['created_at']))) ?></small></article><?php endforeach; ?></div><?php endif; ?></section><?php require 'includes/footer.php'; ?>
